BEGIN TRANSACTION;
UPDATE Orders SET status = 'paid' WHERE order_id = 102;
SELECT status FROM Orders WHERE order_id = 102; -- paid
ROLLBACK;
SELECT status FROM Orders WHERE order_id = 102; -- pending

SET XACT_ABORT ON;
BEGIN TRY
  BEGIN TRANSACTION;
  UPDATE Orders SET status = 'paid' WHERE order_id = 102;
  IF @@ROWCOUNT <> 1 THROW 50001, 'Expected one toy order', 1;
  ROLLBACK TRANSACTION; -- practice: intentionally keep original data
END TRY
BEGIN CATCH
  IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
  THROW;
END CATCH;

BEGIN TRANSACTION;
UPDATE Orders SET status = 'paid'
WHERE order_id = 102 AND status = 'pending';
-- Driver affected rows: 1 on fresh seed, 0 if already changed.
ROLLBACK;

